// Sidebar order comes from the filename prefix.
//
// The autogenerated sidebar only understands an integer prefix, so chapters
// named 06.5-, 08.1-, 08.2-, 08.3- and 12.1- lose their number and pile up at
// the end of the list. An explicit sidebar_position fixes that, and deriving it
// from the filename keeps the order correct across every content sync.
import {readFileSync, writeFileSync, readdirSync, statSync} from 'node:fs';
import {join} from 'node:path';

const PREFIX = /^(\d+(?:\.\d+)?)-/;

/**
 * '08.3-proximity-full-flow-detail.md' -> 8.3
 * 'README.md' -> -1 (the section index reads before chapter 00)
 * anything else -> null
 */
export function positionFromFilename(name) {
  if (/^readme\.md$/i.test(name)) return -1;
  const match = PREFIX.exec(name);
  return match ? Number(match[1]) : null;
}

/** Insert sidebar_position once, keeping the existing frontmatter intact. */
export function ensureSidebarPosition(file, name = file) {
  const position = positionFromFilename(name.split('/').pop());
  if (position === null) return false;
  const text = readFileSync(file, 'utf8');
  if (/^sidebar_position:/m.test(text)) return false;
  const frontmatter = /^---\n([\s\S]*?)\n---\n/.exec(text);
  if (!frontmatter) return false;
  writeFileSync(
    file,
    `---\n${frontmatter[1]}\nsidebar_position: ${position}\n---\n${text.slice(frontmatter[0].length)}`,
  );
  return true;
}

/** Walk a doc tree and normalise every numbered chapter. Returns the count changed. */
export function ensureSidebarPositions(root) {
  let changed = 0;
  const walk = (dir) => {
    for (const entry of readdirSync(dir)) {
      const path = join(dir, entry);
      if (statSync(path).isDirectory()) {
        walk(path);
      } else if (entry.endsWith('.md') && ensureSidebarPosition(path, entry)) {
        changed += 1;
      }
    }
  };
  walk(root);
  return changed;
}
